<?php require_once __DIR__ . '/../bootstrap.php'; $user=require_auth();$id=(int)(body()['id']??$_GET['id']??0);$s=$pdo->prepare('DELETE FROM log_entries WHERE id=?'.($user['role']==='admin'?'':' AND user_id=?'));$params=[$id];if($user['role']!=='admin')$params[]=$user['id'];$s->execute($params);if(!$s->rowCount())respond(false,'Log entry not found.',[],404);respond(true,'Log entry deleted successfully.');
